/// <summary>
/// MPJ-15936 Customer Group Name DCP 20/06/2022
/// </summary>
[ExtensionOf(tableStr(CustAgingLegalEntityView))]
final class METCustAgingLegalEntityView_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_3735_Aged Balance
    /// </summary>
    /// <returns>return outstanding credit limit percent</returns>
    [SysClientCacheDataMethod]
    public display Percent getMETCreditLimitOutstanding()
    {
        Percent metCreditLimitOutstanding;
        
        metCreditLimitOutstanding = this.SumOfCreditLimitMst == 0 ? 0 : (this.SumOfAmountDueMst / this.SumOfCreditLimitMst) * 100;

        return metCreditLimitOutstanding;
    }

    /// <summary>
    /// MPJ-15936 Customer Group Name DCP 20/06/2022
    /// </summary>
    /// <returns>return amount overdue as percent</returns>
    [SysClientCacheDataMethod]
    public display Percent metGetTotalOverDuePercent()
    {
        AmountMST   metCustBalance;
        Percent     metResult;

        metCustBalance = this.metFindCustTable().balancePerDate();

        if(metCustBalance)
        {
            metResult = (this.SumOfAmountDueMst / metCustBalance) * 100;
        }
        else
        {
            metResult = 0;
        }

        return metResult;
    }

    /// <summary>
    /// MPJ-15936 Customer Group Name DCP 20/06/2022
    /// </summary>
    /// <returns>Customer account number</returns>
    public CustTable metFindCustTable()
    {
        CustTable   metCustTable;
        CustAging   metCustAging;

        select metCustTable
        exists join metCustAging
            where   metCustAging.CustTable  == metCustTable.AccountNum
            &&      metCustAging.RecId      == this.CustAging;
        
        return metCustTable;
    }
